<section>
    <p class="eyebrow">Formacao da equipe</p><h1><?= App\Core\View::e($team['name']) ?></h1>
    <p class="muted">Coordenadas: horizontal 0–100 da esquerda para a direita; vertical 0–100 da defesa para o ataque. O cadastro prepara o campo futuro.</p>
    <?php if ($selected): ?><h2><?= App\Core\View::e($selected['name']) ?></h2><ol class="formation-slots"><?php foreach ($selected['slots'] as $slot): ?><li><strong><?= App\Core\View::e($slot['label']) ?></strong> · <?= App\Core\View::e($slot['position_group']) ?> · (<?= App\Core\View::e($slot['horizontal_position']) ?>, <?= App\Core\View::e($slot['vertical_position']) ?>)</li><?php endforeach; ?></ol><?php endif; ?>
    <?php if ($canManage): ?><form method="post" action="<?= App\Core\View::e(App\Core\Config::url('/admin/equipes/' . $team['slug'] . '/formacao')) ?>"><input type="hidden" name="_csrf" value="<?= App\Core\View::e(App\Core\Security::csrfToken()) ?>"><label>Formacao padrao <select name="formation_id" required><option value="">Selecione</option><?php foreach ($formations as $formation): ?><option value="<?= (int) $formation['id'] ?>" <?= $selected && (int) $selected['id'] === (int) $formation['id'] ? 'selected' : '' ?>><?= App\Core\View::e($formation['name']) ?></option><?php endforeach; ?></select></label><button type="submit">Salvar formacao</button></form><?php endif; ?>
    <h2>Formacoes disponiveis</h2><ul><?php foreach ($formations as $formation): ?><li><?= App\Core\View::e($formation['name']) ?> · <?= App\Core\View::e($formation['description']) ?></li><?php endforeach; ?></ul>
    <p><a href="<?= App\Core\View::e(App\Core\Config::url('/admin/equipes/' . $team['slug'])) ?>">Voltar para equipe</a></p>
</section>
